const legendBtn=document.getElementById("open-legend-button"),legendText=document.getElementById("legend-text");legendBtn&&legendText&&legendBtn.addEventListener("click",()=>{legendText.classList.contains("show")?(legendText.classList.remove("show"),legendText.classList.add("hide"),legendBtn.classList.remove("active"),setTimeout(()=>{legendText.style.display="none",legendText.classList.remove("hide")},300)):(legendText.style.display="block",setTimeout(()=>{legendText.classList.add("show"),legendText.classList.remove("hide")},10),legendBtn.classList.add("active"))});const startTime=performance.now();window.addEventListener("load",()=>{const e=(performance.now()-startTime)/1e3;document.getElementById("load-time").textContent=e.toFixed(2)});const start=performance.now();window.addEventListener("load",()=>{const e=document.getElementById("load-time");e&&(e.textContent=((performance.now()-start)/1e3).toFixed(2))});